const root=document.getElementById('app');
function today(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(n,d=1)=>n==null?'—':Number(n).toLocaleString('ko-KR',{maximumFractionDigits:d});
const recent=(arr)=>[...arr].sort((a,b)=>b.date.localeCompare(a.date));
const byDate=(arr,date)=>arr.filter(x=>x.date===date);
function chart(items,key,days=30){const cutoff=new Date();cutoff.setHours(0,0,0,0);cutoff.setDate(cutoff.getDate()-days+1);const data=recent(items).filter(x=>x[key]!=null&&new Date(x.date)>=cutoff).sort((a,b)=>a.date.localeCompare(b.date));if(!data.length)return '<div class="empty">아직 그래프로 표시할 기록이 없습니다.</div>';const vals=data.map(x=>x[key]),min=Math.min(...vals),max=Math.max(...vals),range=Math.max(max-min,1),pts=data.map((x,i)=>({x:data.length===1?160:30+(new Date(x.date)-new Date(data[0].date))*290/Math.max(86400000,new Date(data.at(-1).date)-new Date(data[0].date)),y:130-(x[key]-min)/range*90,v:x[key]}));const line=pts.map((p,i)=>`${i?'L':'M'}${p.x},${p.y}`).join(' ');return `<svg class="chart" viewBox="0 0 350 170" role="img" aria-label="${esc(key)} 추이"><line class="gridline" x1="25" y1="40" x2="325" y2="40"/><line class="gridline" x1="25" y1="85" x2="325" y2="85"/><line class="gridline" x1="25" y1="130" x2="325" y2="130"/><path class="area" d="${line} L${pts.at(-1).x},145 L${pts[0].x},145 Z"/><path class="line" d="${line}"/>${pts.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="3"/>`).join('')}<text x="25" y="160">${esc(data[0].date.slice(5))}</text><text x="285" y="160">${esc(data.at(-1).date.slice(5))}</text></svg><div class="row small muted"><span>최저 ${fmt(min)}</span><span>최고 ${fmt(max)}</span></div>`}
function toast(msg){let old=document.querySelector('.toast');old?.remove();const el=document.createElement('div');el.className='toast';el.textContent=msg;document.body.append(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),3500)}
function updateRestTimer(){const el=document.getElementById('rest-timer');if(!el)return;const left=Math.max(0,Math.ceil((timerEnds-Date.now())/1000));el.classList.toggle('hidden',left===0);el.querySelector('span').textContent=`휴식 ${Math.floor(left/60)}:${String(left%60).padStart(2,'0')}`;if(left===0&&timerEnds){timerEnds=0;clearInterval(timerHandle);timerHandle=null;toast('휴식 시간이 끝났습니다.')}}
function startRestTimer(seconds){timerEnds=Date.now()+seconds*1000;clearInterval(timerHandle);timerHandle=setInterval(updateRestTimer,500);updateRestTimer();persistDraft()}
function stopRestTimer(){timerEnds=0;clearInterval(timerHandle);timerHandle=null;updateRestTimer();persistDraft()}
