function analysisPage(){
 const week=weeklyReport(db),month=monthlyReport(db),big3=threeLiftTotal(db.workouts),parts=partSummary(db,30),load=fatigueProxy(db),names=[...new Set(db.workouts.flatMap(w=>w.exercises.filter(e=>e.kind!=='cardio').map(e=>e.name)))];
 if(!names.includes(analysisExercise))analysisExercise=names[0]||'';
 const selected=allExercises().find(x=>x.name===analysisExercise),trendDB={...db,workouts:db.workouts.map(w=>({...w,exercises:w.exercises.filter(e=>(selected?.id?e.exerciseId===selected.id:e.name===analysisExercise)&&(analysisMachine==='all'||(e.machineId||'')===analysisMachine)).map(e=>({...e,name:analysisExercise}))}))};const trend=analysisExercise?exerciseTrend(trendDB,analysisExercise,analysisDays):[];
 return `<div class="page-head"><div><span class="eyebrow">Analysis</span><h2>운동 분석</h2><p>계산된 기록이며 실제 건강 상태를 판단하지 않습니다.</p></div><button class="button secondary" data-page="workout">운동으로</button></div>
 <div class="grid"><div class="card metric"><span class="sub">최근 7일</span><strong>${week.workoutSessions}<span class="unit"> 회</span></strong><small>${fmt(week.totalVolume,0)} kg · ${fmt(week.totalDuration,0)}분</small></div><div class="card metric"><span class="sub">최근 30일</span><strong>${month.workoutSessions}<span class="unit"> 회</span></strong><small>${fmt(month.totalVolume,0)} kg · ${fmt(month.cardioMinutes,0)}분 유산소</small></div></div>
 <section class="section card"><h3>종목 성장</h3><label class="field">종목<select id="analysis-exercise">${names.map(n=>`<option ${n===analysisExercise?'selected':''}>${esc(n)}</option>`).join('')}</select></label><div class="form-grid"><label class="field">머신<select id="analysis-machine"><option value="all">동작 전체 (머신 혼합)</option><option value="" ${analysisMachine===''?'selected':''}>미지정 / 프리웨이트</option>${(db.machines||[]).map(m=>`<option value="${esc(m.id)}" ${analysisMachine===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label><label class="field">기간<select id="analysis-days"><option value="28" ${analysisDays===28?'selected':''}>4주</option><option value="84" ${analysisDays===84?'selected':''}>12주</option></select></label></div>${trend.length?chart(trend,'best1RM',analysisDays):'<div class="empty">기록된 종목이 없습니다.</div>'}<p class="hint">Epley 추정 1RM. 실제 최대 중량과 다를 수 있습니다.</p></section>
 ${prHTML()}${reviewHTML()}<section class="section"><h3 class="section-title">부위별 기록 · 최근 30일</h3><div class="card">${parts.length?parts.map(x=>`<div class="record"><strong>${esc(x.part)}</strong><span>${x.sets}세트 · ${fmt(x.volume,0)} kg</span></div>`).join(''):'<div class="empty">운동 기록이 쌓이면 표시됩니다.</div>'}</div></section>
 <section class="section card"><h3>부위 지도</h3><div class="atlas-switch"><button class="chip ${analysisAtlasMode==='load'?'active':''}" data-atlas-mode="load" aria-pressed="${analysisAtlasMode==='load'}">최근 추정부하</button><button class="chip ${analysisAtlasMode==='target'?'active':''}" data-atlas-mode="target" aria-pressed="${analysisAtlasMode==='target'}">선택한 종목 타깃</button></div>${analysisAtlasMode==='load'?loadAtlasHTML('analysis'):muscleMapHTML(selected?.primaryMuscleIds||[],selected?.secondaryMuscleIds||[],{key:'analysis-target'})}<p class="hint">타깃은 일반적인 동작 설명이며, 추정부하는 실제 입력한 완료 세트로만 계산합니다.</p></section>
 <section class="section"><h3 class="section-title">주간·월간 요약</h3><div class="grid">${[week,month].map((r,i)=>`<div class="card"><h3>${i?'최근 30일':'최근 7일'}</h3><p class="small">운동 ${r.workoutSessions}회 · ${r.totalSets}세트<br>볼륨 ${fmt(r.totalVolume,0)} kg<br>유산소 ${fmt(r.cardioMinutes,0)}분 · ${fmt(r.distanceKm)} km<br>식단 기록일 ${r.recordedDietDays}일 · 평균 ${fmt(r.averageCalories,0)} kcal<br>체중 변화 ${fmt(r.weightChange)} kg</p></div>`).join('')}</div><p class="hint">식단 평균은 완료/단식일 기준이며 부분 기록일은 제외합니다. 3대 합계 ${fmt(big3.total,0)} kg.</p></section>`
}
function calendarPage(){const d=new Date(selectedDate+'T12:00:00'),y=d.getFullYear(),m=d.getMonth(),first=new Date(y,m,1).getDay(),count=new Date(y,m+1,0).getDate();const has=date=>[...db.body,...db.meals,...db.workouts].some(x=>x.date===date)||dietState(db,date)==='fasting'||(db.settings.restDates||[]).includes(date);let cells=Array.from({length:first},()=>'<span></span>');for(let n=1;n<=count;n++){const date=`${y}-${String(m+1).padStart(2,'0')}-${String(n).padStart(2,'0')}`;cells.push(`<button data-calendar="${date}" class="${has(date)?'filled':''} ${date===today()?'today':''} ${date===selectedDate?'selected':''}">${n}</button>`)}const bs=byDate(db.body,selectedDate),ms=byDate(db.meals,selectedDate),ws=byDate(db.workouts,selectedDate);return `<div class="page-head"><div><span class="eyebrow">History</span><h2>기록 캘린더</h2><p>몸·식단·운동 기록을 날짜별로 확인합니다.</p></div></div><div class="row"><button class="button secondary" data-month="-1">〈</button><h3>${y}년 ${m+1}월</h3><button class="button secondary" data-month="1">〉</button></div><div class="card" style="margin-top:12px"><div class="calendar">${['일','월','화','수','목','금','토'].map(x=>`<span>${x}</span>`).join('')}${cells.join('')}</div></div><section class="section"><h3 class="section-title">${selectedDate} 기록</h3><div class="card"><div class="record"><strong>⚖ 체성분</strong><span>${bs.length?`${fmt(bs.at(-1).weight)} kg`:'미측정'}</span></div><div class="record"><strong>◒ 식단</strong><span>${{partial:'일부 기록',complete:'하루 완료',fasting:'의도적 단식',unrecorded:'미기록'}[dietState(db,selectedDate)]}${ms.length?` · ${fmt(mealTotals(ms).calories,0)} kcal`:''}</span></div><div class="record"><strong>◆ 운동</strong><span>${ws.length?`${ws.length}회 · ${fmt(ws.reduce((s,w)=>s+workoutTotals(w).volume,0),0)} kg`:(db.settings.restDates||[]).includes(selectedDate)?'계획한 휴식':'미기록'}<button class="text-button" id="toggle-rest">휴식 표시 변경</button></span></div></div></section>`}
function settingsPage(){return `<div class="page-head"><div><span class="eyebrow">Settings</span><h2>설정과 백업</h2><p>기록은 현재 이 기기에 저장됩니다.</p></div></div><section class="card"><h3>일일 식단 목표</h3><form id="goal-form" class="form-grid"><label class="field">칼로리<input name="calorieGoal" type="number" min="0" value="${db.settings.calorieGoal}"></label><label class="field">탄수화물 g<input name="carbsGoal" type="number" min="0" value="${db.settings.carbsGoal}"></label><label class="field">단백질 g<input name="proteinGoal" type="number" min="0" value="${db.settings.proteinGoal}"></label><label class="field">지방 g<input name="fatGoal" type="number" min="0" value="${db.settings.fatGoal}"></label><label class="field wide">바벨 자체 중량 kg<input name="barbellWeightKg" type="number" min="0" step="0.5" value="${db.settings.barbellWeightKg??20}"></label><button class="button wide">목표 저장</button></form></section><section class="section card"><h3>데이터 백업·복원</h3><p class="small muted" style="margin-bottom:12px">기기 교체에 대비해 백업 파일을 보관하세요. 복원은 현재 기록을 교체합니다.</p><div class="actions"><button class="button secondary" id="export">백업 파일 저장</button><button class="button secondary" data-modal="restore">백업 파일 복원</button></div></section><section class="section card"><h3>임시 운동 원본</h3><p class="hint">운동 초안은 통합 백업과 별도로 이 기기에 저장됩니다.</p><button class="button secondary" id="draft-export">임시 운동 원본 내보내기</button><button class="button secondary" id="draft-archive-export">복원 전 운동 초안 내보내기</button></section><section class="section card"><h3>연결 예정 기능</h3><div class="record"><span>서버 동기화</span><span class="status-warn">미연결</span></div><div class="record"><span>외부 AI 분석</span><span class="status-warn">미연결</span></div><div class="record"><span>스마트워치</span><span class="status-warn">보류</span></div><p class="hint" style="margin-top:12px">프로토타입에서는 연결된 기능만 작동합니다.</p></section>`}
function modalHTML(){if(!modal)return '';const wrap=(title,content)=>`<div class="modal-backdrop" id="backdrop"><div class="sheet" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="sheet-head"><h2>${esc(title)}</h2><button class="close" id="close" aria-label="닫기">×</button></div>${content}</div></div>`;
 if(modal==='body'){const b=db.body.find(x=>x.id===bodyEditId)||{};return wrap(bodyEditId?'몸 기록 수정':'체중·체성분 기록',`<form id="body-form" class="form-grid">${[['date','측정일','date'],['weight','체중 kg','number'],['bodyFatPct','체지방률 %','number'],['skeletalMuscle','골격근량 kg','number'],['bodyFatMass','체지방량 kg','number'],['bmi','BMI','number'],['score','인바디 점수','number'],['visceralFatLevel','내장지방 레벨','number'],['bmr','기초대사량 kcal','number'],['note','메모','text']].map(([k,label,type])=>`<label class="field">${label}<input name="${k}" type="${type}" ${type==='number'?'min="0" step="any"':''} ${k==='date'?'required':''} value="${esc(b[k]??(k==='date'?today():''))}"></label>`).join('')}<p class="hint wide">출처: ${esc(b.source||'manual')}${b.updatedAt?` · 최근 수정 ${esc(b.updatedAt)}`:''}</p><button class="button wide">기록 저장</button></form>`)}
 if(modal==='machine')return wrap('머신 프로필',machineFormHTML(machineEdit||{},workDraft[machineIndex]?.exerciseId||''));
 if(modal==='custom-exercise')return wrap('나만의 종목',exerciseFormHTML(customEdit||{}));
 if(modal==='batch')return wrap('한 끼 함께 기록',batchHTML(batchRows,batchDate,batchSlot,db.foods||[],db.recipes||[]));
 if(modal==='checkin')return wrap('오늘 상태',checkinHTML());
 if(modal==='meal'){
  const meal=db.meals.find(x=>x.id===mealEditId);
  const recent=recentFoods(db.meals).slice(0,8);
  return wrap(meal?'식단 기록 수정':'식단 기록',mealFormHTML({meal,date:selectedDate,recent,presets:db.foods||[]}));
 }
 if(modal==='workout'||modal==='routine'){
  if(!workDraft.length)workDraft=[{name:'',part:'가슴',kind:'strength',sets:[{weight:0,reps:10,type:'본세트',rpe:null,completed:false}]}];
  const last=(name,current)=>{if(!name)return '';for(const w of recent(db.workouts))for(const e of w.exercises||[])if((current?.exerciseId?e.exerciseId===current.exerciseId:e.name===name)&&(e.machineId||null)===(current?.machineId||null)){const s=e.sets?.at(-1);return s?`${s.weight??0} ${s.unit||'kg'} × ${s.reps??0}회 · ${w.date}`:`${w.date} · ${e.durationMin||0}분`;}return ''};
  return wrap(modal==='routine'?'루틴 저장':'운동 기록',`<button type="button" class="text-button" id="undo-draft" ${undoDraft?'':'disabled'}>최근 종목·세트 변경 되돌리기</button>`+workoutFormHTML({draft:workDraft,meta:workMeta,routine:modal==='routine',latest:last,estimate:(name,ex)=>estimateFor(ex||{name}),catalog:allExercises(),machines:db.machines||[],favorites:db.favorites||[],recentExercises:recentExercises(),selection,routines:db.routines,checkin:{...db.checkins?.[workMeta.date||today()],...workMeta},barbellWeightKg:db.settings.barbellWeightKg??20}));
 }
 if(modal==='inbody')return wrap('인바디 사진 읽기',`<div class="gap"><p class="small muted">사진을 고르면 기기에서 문자 인식을 시도합니다. 읽은 숫자는 반드시 원본과 비교해 주세요.</p><input id="inbody-photo" type="file" accept="image/*"><img id="photo-preview" class="preview hidden" alt="선택한 검사표"><div id="ocr-status" class="alert">사진을 선택해 주세요. OCR 도구를 불러올 수 없으면 아래에 직접 입력하거나 Codex에서 만든 숫자 파일을 가져올 수 있습니다.</div><button class="button" id="ocr-run" disabled>사진에서 숫자 읽기</button><label class="field">인식된 문자 수정<textarea id="ocr-text" rows="7" placeholder="인바디 결과지에서 읽은 글자가 여기에 표시됩니다."></textarea></label><button class="button secondary" id="ocr-parse">문자에서 수치 추출</button><div id="ocr-fields"></div></div>`);
 if(modal==='body-import')return wrap('마웨로그 숫자 파일 가져오기',`<div class="gap"><p class="small muted">Codex가 만든 myweightlog.body JSON 파일을 선택하세요.</p><input id="body-file" type="file" accept=".json,application/json"><div id="import-preview" class="alert">파일을 선택하면 수치를 미리 보여줍니다.</div><button class="button" id="body-confirm" disabled>확인한 수치 저장</button></div>`);
 if(modal==='codex-import')return wrap('식단·운동 숫자 파일 가져오기',`<div class="gap"><p class="small muted">Codex가 만든 myweightlog.meal 또는 myweightlog.workout JSON 파일을 선택하세요. 값을 확인한 다음 입력 화면에서 저장합니다.</p><input id="codex-file" type="file" accept=".json,application/json"><button class="button secondary" id="codex-parse">파일 읽기</button><div id="codex-preview" class="alert">파일의 주요 값을 미리 보여줍니다.</div><button class="button" id="codex-confirm" disabled>입력 화면에서 검토</button></div>`);
 if(modal==='progress-photo')return wrap('눈바디 사진 보관',`<div class="gap"><p class="hint">사진은 이 기기에 저장되며 설정의 통합 백업에 포함됩니다.</p><label class="field">촬영일<input id="progress-date" type="date" value="${today()}"></label><input id="progress-file" type="file" accept="image/*"><button class="button" id="progress-save">사진 저장</button></div>`);
 if(modal==='restore')return wrap('백업 파일 복원',`<div class="gap"><p class="alert">현재 기록 전체를 백업 파일의 내용으로 교체합니다. 먼저 현재 기록을 백업해 주세요.</p><input id="restore-file" type="file" accept=".json,application/json"><button class="button secondary" id="restore-preview">검증 및 미리보기</button><div id="restore-summary" class="hint"></div><button class="button danger" id="restore-confirm" disabled>검증한 백업으로 교체</button></div>`);
 if(modal.startsWith('detail:')){const w=db.workouts.find(x=>x.id===modal.slice(7));if(!w)return '';const t=workoutTotals(w);return wrap(w.title,`<div class="gap"><p class="sub">${w.date} · ${fmt(w.duration,0)}분</p><div class="grid"><div class="card"><span class="sub">총 볼륨</span><h3>${fmt(t.volume,0)} kg</h3></div><div class="card"><span class="sub">세트 / 반복</span><h3>${t.sets} / ${t.reps}</h3></div></div>${w.exercises.map(e=>`<div class="card">${muscleMapHTML(e.primaryMuscleIds||[],e.secondaryMuscleIds||[],{key:'detail-'+e.id})}<h3>${esc(e.name)} <small class="muted">${esc(e.part)}</small></h3>${e.sets.map(s=>`<div class="record"><span>${esc(s.type)} · ${s.completed===false?'미완료':'완료'}</span><strong class="${s.completed===false?'muted':''}">${fmt(s.weight)} ${esc(s.unit||'kg')} × ${s.reps}회</strong></div>`).join('')}</div>`).join('')}<p class="hint">${esc(w.note)}</p><div class="actions"><button class="button secondary" id="share-workout">결과 이미지 저장</button><button class="button danger" data-delete="workouts:${esc(w.id)}">운동 삭제</button></div></div>`)}return ''}
function render(){const oldSheet=document.querySelector?.('.sheet'),keep=renderedModal===modal&&!!modal,scroll=keep?(oldSheet?.scrollTop||0):0,openDetails=keep?Array.from(oldSheet?.querySelectorAll?.('details')||[]).map(d=>d.open):[];persistDraft();root.innerHTML=`<div class="shell">${header}<main>${recoveryBanner()}${({home,body:bodyPage,food:foodPage,workout:workoutPage,analysis:analysisPage,calendar:calendarPage,settings:settingsPage}[page]||home)()}</main></div>${nav()}${page==='home'?'<button class="fab" data-modal="quick" aria-label="빠른 기록">＋</button>':''}${modal==='quick'?`<div class="modal-backdrop" id="backdrop"><div class="sheet"><div class="sheet-head"><h2>무엇을 기록할까요?</h2><button class="close" id="close">×</button></div><div class="gap"><button class="button secondary" data-modal="body">⚖ 체중·인바디</button><button class="button secondary" data-modal="meal">◒ 식단</button><button class="button secondary" data-modal="workout">◆ 운동</button></div></div></div>`:modalHTML()}<div id="rest-timer" class="rest-timer hidden" role="status"><span></span><button id="timer-stop">종료</button></div>`;if(modal==='meal')mealPreview(document.getElementById('meal-form'),scaleNutrition);const newSheet=document.querySelector?.('.sheet');if(keep&&newSheet){Array.from(newSheet.querySelectorAll('details')).forEach((d,i)=>d.open=!!openDetails[i]);newSheet.scrollTop=scroll;globalThis.requestAnimationFrame?.(()=>{if(document.querySelector('.sheet')===newSheet)newSheet.scrollTop=scroll})}renderedModal=modal;updateRestTimer()}
function download(name,data,type='application/json'){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function ocrFields(data){ocrDraft=data;document.getElementById('ocr-fields').innerHTML=`<div class="form-grid">${[['date','측정일','date'],['weight','체중 kg','number'],['skeletalMuscle','골격근량 kg','number'],['bodyFatPct','체지방률 %','number'],['bodyFatMass','체지방량 kg','number'],['bmi','BMI','number'],['score','인바디 점수','number'],['visceralFatLevel','내장지방 레벨','number'],['bmr','기초대사량 kcal','number']].map(([key,label,type])=>`<label class="field">${label}<input data-ocr-field="${key}" type="${type}" step="any" value="${esc(data[key]??(key==="date"?today():""))}"></label>`).join('')}<button class="button wide" id="ocr-save">원본과 확인한 수치 저장</button></div>`}
async function readFile(input){const file=input?.files?.[0];if(!file)throw Error('파일을 선택해 주세요.');return file.text()}
root.addEventListener('click',async event=>{
 const target=event.target.closest('button,[data-page],[data-metric],[data-filter-part]');if(!target)return;
 try{
  if(backupBusy){toast('백업·복원이 진행 중입니다. 완료될 때까지 기다려 주세요.');return}
  if(getStorageStatus().blocked&&!target.dataset.page&&!['recovery-export','retry-recovery','restore-preview','restore-confirm','close','draft-export','draft-archive-export'].includes(target.id)&&target.dataset.modal!=='restore')throw Error('기존 기록 보호를 위해 복구가 필요합니다.');
  if(['workEdit','program','reload','routine'].some(k=>target.dataset[k]!==undefined)||(target.id==='codex-confirm'&&codexDraft?.kind==='workouts')){const pending=readSession();if(pending?.exercises?.some(e=>e.name)&&!confirm('작성 중인 임시 운동이 있습니다. 새로 선택한 운동으로 교체할까요? 취소하면 기존 초안을 유지합니다.'))return;clearSession();savedDraft=null}
  if(target.dataset.page){persistDraft();page=target.dataset.page;modal=null;render();return}
  if(target.dataset.modal){persistDraft();bodyEditId=null;if(target.dataset.modal==='workout'&&readSession()){resumeSession();return}if(target.dataset.modal==='batch'){batchRows=[blankFood()];batchCopy=false;batchDate=selectedDate;batchSlot='아침'}modal=target.dataset.modal;mealEditId=null;workEditId=null;routineEditId=null;if(modal==='workout'||modal==='routine'){workDraft=[];workMeta={date:today(),title:modal==='routine'?'나의 루틴':'오늘의 운동',duration:'',condition:'',note:''}}render();return}
  if(target.id==='close'||target.id==='backdrop'){persistDraft();modal=['machine','custom-exercise'].includes(modal)?profileReturn:null;render();return}
  if(await enhancedClick(target))return;
  if(target.dataset.metric){bodyMetric=target.dataset.metric;render();return}
  if(target.dataset.calendar){selectedDate=target.dataset.calendar;render();return}
  if(target.dataset.month){const d=new Date(selectedDate+'T12:00:00');d.setMonth(d.getMonth()+Number(target.dataset.month),1);selectedDate=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-01`;render();return}
  if(target.dataset.mealEdit){mealEditId=target.dataset.mealEdit;modal='meal';render();return}
  if(target.dataset.workEdit){const w=db.workouts.find(x=>x.id===target.dataset.workEdit);if(!w)return;workEditId=w.id;workDraft=structuredClone(w.exercises);workMeta={date:w.date,title:w.title,duration:w.duration,condition:w.condition,note:w.note};modal='workout';render();return}
  if(target.dataset.routineEdit){const r=db.routines.find(x=>x.id===target.dataset.routineEdit);if(!r)return;routineEditId=r.id;workDraft=structuredClone(r.exercises);workMeta={title:r.title,date:today()};modal='routine';render();return}
  if(target.dataset.routineDelete){if(confirm('이 루틴을 삭제할까요?')){db=remove(db,'routines',target.dataset.routineDelete);render();toast('루틴을 삭제했습니다.')}return}
  if(target.dataset.progressDelete){if(confirm('이 사진을 삭제할까요?')){await deleteProgressPhoto(target.dataset.progressDelete);await refreshProgressPhotos();toast('사진을 삭제했습니다.')}return}
  if(target.dataset.progressExport){const item=progressPhotos.find(x=>x.id===target.dataset.progressExport);if(!item)return;const ext=item.type==='image/png'?'png':item.type==='image/webp'?'webp':'jpg';const a=document.createElement('a');a.href=item.url;a.download=`myweightlog-progress-${item.date}-${item.id.slice(0,6)}.${ext}`;a.click();toast('사진 파일 저장을 시작했습니다.');return}
  if(target.dataset.program){const [id,index]=target.dataset.program.split(':');const template=createRoutineFromProgram(id,Number(index));workDraft=template.exercises.map(e=>({...e,sets:e.sets.map(s=>({...s,completed:false}))}));workMeta={date:today(),title:template.title,duration:'',condition:'',note:''};workEditId=null;modal='workout';render();toast('시작용 구성입니다. 중량을 직접 확인해 주세요.');return}
  if(target.dataset.foodChoice){const [source,index]=target.dataset.foodChoice.split(':');const food=source==='preset'?(db.foods||[])[Number(index)]:recentFoods(db.meals)[Number(index)];const form=document.getElementById('meal-form');if(!food||!form)return;for(const key of ['name','servingUnit','calories','carbs','protein','fat'])if(form.elements[key])form.elements[key].value=food[key]??'';form.elements.servingQty.value='1';mealPreview(form,scaleNutrition);return}
  if(target.dataset.foodSave){const m=db.meals.find(x=>x.id===target.dataset.foodSave);if(!m)return;db=save({...db,foods:upsertFoodPreset(db.foods||[],{name:m.name,servingUnit:m.servingUnit,calories:m.calories/(m.servingQty||1),carbs:m.carbs/(m.servingQty||1),protein:m.protein/(m.servingQty||1),fat:m.fat/(m.servingQty||1)})});toast('자주 먹는 음식에 저장했습니다.');return}
  if(target.dataset.delete){const [kind,id]=target.dataset.delete.split(':');if(confirm('이 기록을 삭제할까요?')){const removed=db[kind].find(x=>x.id===id);const next={...db,[kind]:db[kind].filter(x=>x.id!==id)};if(kind==='meals')next.dayStates={...db.dayStates,[removed.date]:next.meals.some(x=>x.date===removed.date)?'partial':'unrecorded'};db=save(next);modal=null;render();toast('기록을 삭제했습니다.')}return}
  if(target.dataset.reload){const w=db.workouts.find(x=>x.id===target.dataset.reload);if(!w)return;workEditId=null;workDraft=structuredClone(w.exercises).map(e=>({...e,sets:e.sets.map(s=>({...s,id:uid(),completed:false}))}));workMeta={date:today(),title:w.title,duration:w.duration,condition:'',note:''};modal='workout';render();return}
  if(target.dataset.detail){modal='detail:'+target.dataset.detail;render();return}
  if(target.dataset.routine){const r=db.routines.find(x=>x.id===target.dataset.routine);if(!r)return;workEditId=null;workDraft=structuredClone(r.exercises).map(e=>({...e,sets:e.sets.map(s=>({...s,targetWeight:s.weight,targetReps:s.reps,targetUnit:s.unit||'kg',completed:false}))}));workMeta={date:today(),title:r.title,duration:'',condition:'',note:''};modal='workout';render();return}
  if(target.id==='add-ex'){workDraft.push({name:'',part:'가슴',kind:'strength',sets:[{weight:0,reps:10,type:'본세트',completed:false}]});render();return}
  if(['assist','addSet','copySet','removeSet','removeEx','moveEx','applyPrevious','pickExercise'].some(k=>target.dataset[k]!==undefined)||target.id==='add-ex')undoDraft=structuredClone(workDraft);
  if(target.dataset.assist){const state=cleanCheckin({...db.checkins?.[workMeta.date||today()],...workMeta});if(state.pain===true||state.energy!==null&&state.energy<=2||state.sleep!==null&&state.sleep<=2||state.soreness!==null&&state.soreness>=4)throw Error('오늘 상태를 반영해 중량 제안을 보류합니다. 직접 입력하거나 휴식을 선택하세요.');const [ei,mode]=target.dataset.assist.split(':');const ex=workDraft[Number(ei)];ex.sets=suggestSets(mode,estimateFor(ex)).map(s=>({...s,completed:false,targetWeight:s.weight,targetReps:s.reps,targetUnit:s.unit}));render();toast('과거 기록으로 만든 초안입니다. 중량과 횟수를 확인해 주세요.');return}
  if(target.dataset.addSet!==undefined){workDraft[Number(target.dataset.addSet)].sets.push({weight:0,reps:10,type:'본세트',completed:false});render();return}
  if(target.dataset.copySet){const [ei,si]=target.dataset.copySet.split(':').map(Number);const ex=workDraft[ei];ex.sets.splice(si+1,0,{...structuredClone(ex.sets[si]),id:uid(),completed:false});render();return}
  if(target.dataset.removeSet){const [ei,si]=target.dataset.removeSet.split(':').map(Number);workDraft[ei].sets.splice(si,1);render();return}
  if(target.dataset.removeEx!==undefined){workDraft.splice(Number(target.dataset.removeEx),1);render();return}
  if(target.dataset.timer){startRestTimer(Number(target.dataset.timer));return}
  if(target.id==='timer-stop'){stopRestTimer();return}
  if(target.id==='plate-calc'){const value=document.getElementById('plate-total')?.value;if(!value)throw Error('바벨 총 중량을 입력해 주세요.');const side=plateLoadPerSide(Number(value),db.settings.barbellWeightKg??20);document.getElementById('plate-result').textContent=`한쪽에 ${fmt(side)} kg씩 올리세요.`;return}
  if(target.id==='progress-save'){const file=document.getElementById('progress-file')?.files?.[0],date=document.getElementById('progress-date')?.value;if(!validDate(date))throw Error('사진 날짜를 확인해 주세요.');await saveProgressPhoto(file,date);modal=null;page='body';await refreshProgressPhotos();toast('사진을 이 기기에 저장했습니다.');return}
  if(target.id==='codex-parse'){const file=document.getElementById('codex-file')?.files?.[0];if(!file)throw Error('숫자 파일을 선택해 주세요.');codexDraft=parseCodexRecord(JSON.parse(await file.text()));document.getElementById('codex-preview').textContent=codexDraft.kind==='meals'?`식단 · ${codexDraft.record.date} · ${codexDraft.record.name} · ${fmt(codexDraft.record.calories,0)} kcal`:`운동 · ${codexDraft.record.date} · ${codexDraft.record.title} · ${codexDraft.record.exercises.length}종목`;document.getElementById('codex-confirm').disabled=false;return}
  if(target.id==='codex-confirm'){if(!codexDraft)throw Error('먼저 파일을 읽어 주세요.');if(codexDraft.kind==='meals'){const m=codexDraft.record;mealEditId=null;selectedDate=m.date;modal='meal';render();const f=document.getElementById('meal-form');for(const [key,value] of Object.entries(m)){if(f.elements[key])f.elements[key].value=['calories','carbs','protein','fat'].includes(key)?value/(m.servingQty||1):value}mealPreview(f,scaleNutrition)}else{workEditId=null;workDraft=structuredClone(codexDraft.record.exercises);workMeta={...codexDraft.record};modal='workout';render()}codexDraft=null;toast('수치를 확인하고 저장해 주세요.');return}
  if(target.id==='export'){if(getStorageStatus().blocked)throw Error('저장소 원본을 먼저 보존하고 복구해 주세요.');if(backupBusy)return;backupBusy=true;try{const backup=await createBackup(db);download(`myweightlog-backup-${today()}.json`,JSON.stringify(backup));toast('기록·사진 통합 백업을 저장했습니다.')}finally{backupBusy=false}return}
  if(target.id==='restore-preview'){restoreCandidate=null;document.getElementById('restore-confirm').disabled=true;const raw=JSON.parse(await readFile(document.getElementById('restore-file')));const checked=await validateBackup(raw);restoreCandidate=raw;document.getElementById('restore-summary').textContent=`몸 ${checked.db.body.length}건 · 식단 ${checked.db.meals.length}건 · 운동 ${checked.db.workouts.length}건 · 사진 ${checked.photos?.length??0}장${checked.legacy?' · 이전 숫자 백업: 기존 사진 유지':''}`;document.getElementById('restore-confirm').disabled=false;return}
  if(target.id==='restore-confirm'){if(!restoreCandidate||backupBusy)return;if(!confirm('검증된 백업으로 현재 기록을 교체할까요? 현재 작성 중인 임시 운동은 별도 원본으로 보존한 뒤 종료합니다.'))return;backupBusy=true;try{if(rawSession())localStorage.setItem('myweightlog.draft.before-restore',rawSession());db=await restoreBackup(restoreCandidate);try{clearSession()}catch{draftWarning='복원 전 임시 기록을 정리하지 못했습니다. 설정에서 내보내고 삭제하세요.'}workDraft=[];workMeta={};workEditId=null;savedDraft=null;restoreCandidate=null;modal=null;await refreshProgressPhotos();render();toast('백업을 복원했습니다.')}finally{backupBusy=false}return}
  if(target.id==='body-confirm'){const raw=JSON.parse(await readFile(document.getElementById('body-file')));db=add(db,'body',importBody(raw));modal=null;page='body';render();toast('체성분 기록을 가져왔습니다.');return}
  if(target.id==='ocr-parse'){ocrFields(extractInbody(document.getElementById('ocr-text').value));return}
  if(target.id==='ocr-save'){const data={};document.querySelectorAll('[data-ocr-field]').forEach(x=>data[x.dataset.ocrField]=x.value);db=add(db,'body',cleanBody({...data,source:'photo-reviewed'}));modal=null;page='body';render();toast('확인한 인바디 수치를 저장했습니다.');return}
  if(target.id==='ocr-run'){await runOCR();return}
  if(target.id==='share-workout'){await shareWorkout(db.workouts.find(x=>x.id===modal.slice(7)));return}
 }catch(err){toast(err.message||'작업에 실패했습니다.')}
});
root.addEventListener('change',async event=>{
 const t=event.target;
 try{
 if(enhancedChange(t))return;
 if(t.id==='restore-file'){restoreCandidate=null;document.getElementById('restore-confirm').disabled=true;return}
 if(t.id==='machine-photo'){await readMachinePhoto(t);return}
 if(t.id==='analysis-machine'){analysisMachine=t.value;render();return}
 if(t.id==='analysis-days'){analysisDays=Number(t.value);render();return}
 if(t.id==='period'){period=Number(t.value);render();return}
 if(t.id==='selected-date'){selectedDate=t.value;render();return}
 if(t.id==='analysis-exercise'){analysisExercise=t.value;analysisMachine='all';render();return}
 if(t.id==='body-file'){try{const b=importBody(JSON.parse(await readFile(t)));document.getElementById('import-preview').textContent=`${b.date} · 체중 ${fmt(b.weight)} kg · 체지방률 ${fmt(b.bodyFatPct)}% · 골격근량 ${fmt(b.skeletalMuscle)} kg`;document.getElementById('body-confirm').disabled=false}catch(err){document.getElementById('import-preview').textContent=err.message;document.getElementById('body-confirm').disabled=true}return}
 if(t.id==='inbody-photo'){const f=t.files?.[0];if(f){const img=document.getElementById('photo-preview');img.src=URL.createObjectURL(f);img.classList.remove('hidden');document.getElementById('ocr-run').disabled=false;document.getElementById('ocr-status').textContent='사진이 준비됐습니다. 숫자 읽기를 눌러 주세요.'}return}
 if(t.dataset.ex){const ex=workDraft[Number(t.closest('[data-ei]').dataset.ei)];ex[t.dataset.ex]=t.value;if(t.dataset.ex==='name'){const match=searchExercises(t.value).find(x=>x.name===t.value);if(match){ex.part=match.part;ex.kind=match.kind;render()}}else if(t.dataset.ex==='kind')render();return}
 if(t.dataset.set){const row=t.closest('[data-si]'),set=workDraft[Number(t.closest('[data-ei]').dataset.ei)].sets[Number(row.dataset.si)];set[t.dataset.set]=t.type==='checkbox'?t.checked:t.value;return}
 if(t.closest('#workout-form')&&t.name){workMeta[t.name]=t.value;return}
 if(t.closest('#meal-form'))mealPreview(t.form,scaleNutrition);
 }catch(e){toast(e.message)}finally{persistDraft()}
});
root.addEventListener('input',event=>{
 const t=event.target;
 try{
 if(enhancedInput(t))return;
 if(t.dataset.ex){workDraft[Number(t.closest('[data-ei]').dataset.ei)][t.dataset.ex]=t.value;return}
 if(t.dataset.set){const row=t.closest('[data-si]');workDraft[Number(t.closest('[data-ei]').dataset.ei)].sets[Number(row.dataset.si)][t.dataset.set]=t.type==='checkbox'?t.checked:t.value;return}
 if(t.closest('#workout-form')&&t.name)workMeta[t.name]=t.value;
 if(t.closest('#meal-form'))mealPreview(t.form,scaleNutrition);
 }catch(e){toast(e.message)}finally{persistDraft()}
});
root.addEventListener('submit',event=>{
 event.preventDefault();const form=event.target,d=Object.fromEntries(new FormData(form));
 try{
  if(backupBusy)throw Error('백업·복원 완료 후 저장해 주세요.');
  if(getStorageStatus().blocked)throw Error('기존 기록 보호를 위해 먼저 복구해 주세요.');
  if(form.id==='machine-form'){const item=cleanMachine({...d,id:d.recordId,photoDataUrl:machinePhoto});db=save({...db,machines:[...(db.machines||[]).filter(x=>x.id!==item.id),item]});if(machineIndex!==null&&workDraft[machineIndex]){workDraft[machineIndex].machineId=item.id;for(const set of workDraft[machineIndex].sets)if(Number(set.weight)===0)set.unit=item.unit}modal=profileReturn;render();toast('머신을 저장했습니다.');return}
  if(form.id==='custom-exercise-form'){const fd=new FormData(form);const item=cleanCustomExercise({...d,id:d.recordId,aliases:d.aliases.split(',').map(x=>x.trim()).filter(Boolean),primaryMuscleIds:fd.getAll('primaryMuscleIds'),secondaryMuscleIds:fd.getAll('secondaryMuscleIds')});db=save({...db,customExercises:[...(db.customExercises||[]).filter(x=>x.id!==item.id),item]});modal=profileReturn;render();toast('종목을 저장했습니다.');return}
  if(form.id==='body-form'){const prior=db.body.find(x=>x.id===bodyEditId);const b=cleanBody({...prior,...d,id:prior?.id,updatedAt:new Date().toISOString()});db=prior?replace(db,'body',b):add(db,'body',b);bodyEditId=null;page='body'}
  else if(form.id==='batch-form'){const rows=batchMeals(batchRows,d.date,d.slot).map((x,i)=>({...x,slot:batchRows[i].slot||d.slot,copyKey:batchCopy?`${batchRows[i].id}:${d.date}`:''}));if(batchCopy&&rows.some(x=>db.meals.some(m=>m.copyKey&&m.copyKey===x.copyKey)))throw Error('이미 복사한 식사가 있습니다. 중복을 확인해 주세요.');let next={...db,meals:[...db.meals,...rows],dayStates:{...db.dayStates,[d.date]:'partial'}};if((d.recipeName||'').trim())next.recipes=[...(db.recipes||[]),createRecipe(d.recipeName,rows)];db=save(next);selectedDate=d.date;page='food';batchRows=[]}
  else if(form.id==='checkin-form'){db=save({...db,checkins:{...db.checkins,[today()]:cleanCheckin(d)}});page='workout'}
  else if(form.id==='meal-form'){
   const total=scaleNutrition({calories:d.calories,carbs:d.carbs,protein:d.protein,fat:d.fat},d.servingQty);
   const prior=db.meals.find(x=>x.id===mealEditId);
   const meal=cleanMeal({...prior,...d,...total,id:prior?.id,updatedAt:new Date().toISOString()});
   db=save({...db,meals:prior?db.meals.map(x=>x.id===prior.id?meal:x):[...db.meals,meal],dayStates:{...db.dayStates,[d.date]:'partial'}});selectedDate=d.date;page='food';mealEditId=null;
  }
  else if(form.id==='workout-form'){
   if(modal==='routine'){
    const exercises=cleanWorkout({date:today(),exercises:workDraft}).exercises;
    const prior=db.routines.find(x=>x.id===routineEditId),routine={id:prior?.id||uid(),title:d.title,exercises};
    db=prior?replace(db,'routines',routine):add(db,'routines',routine);routineEditId=null;page='workout';
   }else{
    const prior=db.workouts.find(x=>x.id===workEditId),workout=cleanWorkout({...prior,...d,id:prior?.id,sourceDraftId:savedDraft?.id||prior?.sourceDraftId,exercises:workDraft,updatedAt:new Date().toISOString()});
    const checkin=cleanCheckin(d);db=save({...db,workouts:prior?db.workouts.map(x=>x.id===prior.id?workout:x):[...db.workouts,workout],checkins:{...db.checkins,[d.date]:checkin}});workEditId=workout.id;try{clearSession()}catch(e){draftWarning='운동은 저장됐지만 임시 기록 정리에 실패했습니다.';toast(draftWarning)}savedDraft=null;workEditId=null;page='workout';
   }
  }
  else if(form.id==='goal-form'){db=save({...db,settings:{...db.settings,...Object.fromEntries(Object.entries(d).map(([k,v])=>[k,Math.max(0,Number(v)||0)]))}})}
  modal=null;workDraft=[];workMeta={};render();toast('저장했습니다.');
 }catch(err){toast(err.message)}
});
function allExercises(){return [...EXERCISE_CATALOG,...(db.customExercises||[])]}
function recentExercises(){const seen=new Set();return recent(db.workouts).flatMap(w=>w.exercises).filter(e=>{const key=e.exerciseId||e.name;if(seen.has(key))return false;seen.add(key);return true})}
function previousExercise(ex){return recent(db.workouts).flatMap(w=>w.exercises).find(e=>(ex.exerciseId?e.exerciseId===ex.exerciseId:e.name===ex.name)&&(e.machineId||null)===(ex.machineId||null))}
function persistDraft(){if(modal!=='workout'||getStorageStatus().blocked||draftWarning)return;try{writeSession({exercises:workDraft,meta:workMeta,editId:workEditId,timerEnds});savedDraft=readSession()}catch(e){draftWarning='임시 저장 실패: '+e.message;toast(draftWarning)}}
function resumeSession(){const x=readSession();if(!x)return;if(db.workouts.some(w=>w.sourceDraftId===x.id)){savedDraft=null;try{clearSession()}catch{}toast('이미 저장된 운동입니다. 운동 일지에서 수정하세요.');render();return}workDraft=structuredClone(x.exercises);workMeta={...x.meta};workEditId=x.editId||null;timerEnds=x.timerEnds||0;modal='workout';render();toast('임시 운동 기록을 복구했습니다.')}
function sessionControls(){return `<section class="section card"><h3>작성 중인 운동</h3>${savedDraft?`<p class="hint">${esc(savedDraft.meta?.title||'운동')} · ${savedDraft.exercises?.length||0}종목</p><div class="actions"><button class="button" id="resume-session">이어서 기록</button><button class="button secondary" id="discard-session">임시 기록 삭제</button></div>`:'<p class="hint">운동 중 입력은 이 기기에 임시 저장됩니다.</p>'}${draftWarning?`<p role="alert">${esc(draftWarning)}</p><button class="button secondary" id="draft-export">원본 내보내기</button>${savedDraft?'':'<button class="button secondary" id="discard-session">손상 초안 초기화</button>'}`:''}</section>`}
function recoveryBanner(){const state=getStorageStatus();return state.blocked?`<section class="card" role="alert"><h2>저장소 복구가 필요합니다</h2><p>기존 원본은 보존했으며 덮어쓰기를 차단했습니다. ${esc(state.reason||'')}</p><div class="actions"><button class="button" id="recovery-export">손상 원본 내려받기</button><button class="button secondary" data-modal="restore">정상 백업으로 복구</button><button class="button secondary" id="retry-recovery">중단된 복원 다시 복구</button></div></section>`:''}
function dietControls(){const state=dietState(db,selectedDate);return `<section class="section card"><h3>하루 기록 상태</h3><div class="chip-row">${[['unrecorded','미기록'],['partial','일부 기록'],['complete','하루 완료'],['fasting','의도적 단식']].map(([k,v])=>`<button class="chip ${state===k?'active':''}" data-diet-state="${k}" aria-pressed="${state===k}">${v}</button>`).join('')}</div><p class="hint">평균은 하루 완료·단식일만 사용합니다. 일부 기록은 완전한 하루 섭취량으로 계산하지 않습니다.</p><div class="actions"><button class="button secondary" data-modal="meal">음식 하나 입력</button><button class="button secondary" id="copy-meals">다른 날·끼니 복사</button></div></section>`}
function checkinHTML(){const c=db.checkins?.[today()]||{};return `<form id="checkin-form" class="gap"><p class="hint">${today()} · 기록 기반 제안을 위한 자가 입력입니다. 비워두면 미확인으로 표시합니다.</p>${[['sleep','수면 만족도'],['energy','전신 에너지'],['soreness','근육통 정도']].map(([k,label])=>`<label class="field">${label} (1 낮음 · 5 높음)<select name="${k}"><option value="">미입력</option>${[1,2,3,4,5].map(n=>`<option value="${n}" ${Number(c[k])===n?'selected':''}>${n}</option>`).join('')}</select></label>`).join('')}<label class="field">통증·부상 우려<select name="pain"><option value="">미확인</option><option value="false" ${c.pain===false?'selected':''}>없음</option><option value="true" ${c.pain===true?'selected':''}>있음</option></select></label><button class="button">오늘 상태 저장</button></form>`}
function recommendationView(){const r=recommendWorkout(db,today());return {title:r.title||r.part||({hold:'오늘은 제안 보류',insufficient:'기록이 더 필요합니다',light:'부담을 낮출 날',limited:'정보가 부족한 참고 후보',ready:'오늘의 운동 후보'}[r.status])||'기록 기반 운동 초안',reason:r.reason||r.reasons?.join(' · ')||'최근 기록과 오늘 상태를 함께 확인하세요.',note:r.note||r.missing?.join(' · ')||'추정 정보입니다. 운동 부위와 강도는 직접 결정하세요.',raw:r}}
function recommendationHTML(){const v=recommendationView();return `<h3>${esc(v.title)}</h3><p>${esc(v.reason)}</p><p class="hint">${esc(v.note)}</p>${(v.raw.suggestions||[]).map(x=>`<div class="record"><strong>${esc(x.name)}</strong><small>${esc(x.reason)}</small></div>`).join('')}<p class="hint">미확인: ${esc(v.raw.missing?.join(', ')||'없음')} · 오늘 상태는 자가 입력이며 실제 회복을 측정한 값이 아닙니다.</p><button class="button secondary" id="apply-recommendation">초안을 확인·수정</button>`}
function prHTML(){const rows=exercisePRs(db);return `<section class="section card"><h3>종목·머신별 최고 기록</h3><p class="hint">완료 세트만 집계합니다. 단위는 kg로 환산하며 다른 머신의 표시 중량은 동일 실부하로 비교하지 않습니다.</p>${rows.map(x=>`<div class="record"><div><strong>${esc(x.name||x.exerciseName||'운동')}</strong><small>${esc((db.machines||[]).find(m=>m.id===x.machineId)?.model||'머신 미지정')}</small></div><span>최대 ${fmt(x.maxWeight??x.maxWeightKg)} kg<br>최대 ${fmt(x.maxReps)}회 · 세트 볼륨 ${fmt(x.maxSetVolume)} kg<br>추정 1RM ${fmt(x.best1RM??x.estimated1RM)} kg</span></div>`).join('')||'<p class="hint">완료된 기록이 없습니다.</p>'}</section>`}
async function enhancedClick(t){
 if(t.dataset.atlasMode){analysisAtlasMode=t.dataset.atlasMode;render();return true}
 if(t.dataset.bodyEdit){bodyEditId=t.dataset.bodyEdit;modal='body';render();return true}
 if(t.id==='resume-session'){resumeSession();return true}
 if(t.id==='discard-session'){if(confirm('작성 중인 운동을 삭제할까요?')){clearSession();draftWarning='';savedDraft=null;workDraft=[];workMeta={};render()}return true}
 if(t.id==='draft-archive-export'){download('myweightlog-draft-before-restore.json',localStorage.getItem('myweightlog.draft.before-restore')||'{}');return true}
 if(t.id==='draft-export'){download('myweightlog-draft.json',rawSession()||localStorage.getItem('myweightlog.draft.before-restore')||'{}');return true}
 if(t.id==='recovery-export'){download('myweightlog-recovery.txt',getRecoveryRaw()||'','text/plain');return true}
 if(t.id==='retry-recovery'){await recoverInterruptedRestore();db=load();render();return true}
 if(t.dataset.dietState){db=save(setDietState(db,selectedDate,t.dataset.dietState));render();return true}
 if(t.id==='copy-meals'){const from=prompt('복사할 날짜 (YYYY-MM-DD)',today());if(from===null)return true;if(!validDate(from))throw Error('날짜를 확인해 주세요.');const slot=prompt('끼니 이름을 입력하세요. 전체는 빈칸입니다.','');if(slot===null)return true;const candidates=byDate(db.meals,from).filter(x=>!slot||x.slot===slot);if(!candidates.length)throw Error('복사할 식사가 없습니다.');batchRows=candidates.map(x=>({...x,...Object.fromEntries(['calories','carbs','protein','fat'].map(k=>[k,x[k]==null?'':x[k]/(x.servingQty||1)]))}));batchCopy=true;batchDate=selectedDate;batchSlot=slot||'아침';modal='batch';render();toast('분량·날짜·끼니를 확인한 뒤 저장하세요.');return true}
 if(t.id==='batch-add'){batchRows.push(blankFood());render();return true}
 if(t.dataset.batchRemove!==undefined){batchRows.splice(Number(t.dataset.batchRemove),1);render();return true}
 if(t.dataset.batchPreset!==undefined){batchRows.push({...db.foods[Number(t.dataset.batchPreset)],servingQty:1,source:'manual'});if(batchRows[0]?.name==='')batchRows.shift();render();return true}
 if(t.dataset.batchRecipe){const r=db.recipes.find(x=>x.id===t.dataset.batchRecipe);const rows=recipeMeals(r,batchDate,batchSlot,1);batchRows.push(...rows.map(x=>({...x,...Object.fromEntries(['calories','carbs','protein','fat'].map(k=>[k,x[k]==null?'':x[k]/(x.servingQty||1)]))})));if(batchRows[0]?.name==='')batchRows.shift();render();return true}
 if(t.id==='toggle-rest'){if(byDate(db.workouts,selectedDate).length)throw Error('운동 기록이 있는 날입니다.');const dates=db.settings.restDates||[];db=save({...db,settings:{...db.settings,restDates:dates.includes(selectedDate)?dates.filter(x=>x!==selectedDate):[...dates,selectedDate]}});render();return true}
 if(t.id==='undo-draft'){if(undoDraft){workDraft=undoDraft;undoDraft=null;render()}return true}
 if(['moveEx','applyPrevious','pickExercise'].some(k=>t.dataset[k]!==undefined))undoDraft=structuredClone(workDraft);
 if(t.dataset.exerciseTab){selection.tab=t.dataset.exerciseTab;render();return true}
 if(t.dataset.filterPart){selection.part=t.dataset.filterPart;render();return true}
 if(t.dataset.filterEquipment){selection.equipment=t.dataset.filterEquipment;render();return true}
 if(t.dataset.toggleFavorite){const id=t.dataset.toggleFavorite;db=save({...db,favorites:(db.favorites||[]).includes(id)?db.favorites.filter(x=>x!==id):[...(db.favorites||[]),id]});render();return true}
 if(t.dataset.pickExercise){const item=allExercises().find(x=>x.id===t.dataset.pickExercise);if(!item)return true;const ex={...structuredClone(item),id:uid(),exerciseId:item.id,machineId:null,sets:[{id:uid(),weight:0,unit:'kg',reps:10,type:'본세트',completed:false}]};const prev=previousExercise(ex);if(prev)ex.sets=prev.sets.map(s=>({...s,id:uid(),completed:false}));if(workDraft.length===1&&!workDraft[0].name)workDraft=[];workDraft.push(ex);render();return true}
 if(t.dataset.applyPrevious!==undefined){const ex=workDraft[Number(t.dataset.applyPrevious)],prev=previousExercise(ex);if(!prev)throw Error('같은 종목·머신의 지난 기록이 없습니다.');ex.sets=prev.sets.map(s=>({...s,id:uid(),completed:false,targetWeight:s.weight,targetReps:s.reps,targetUnit:s.unit||'kg'}));render();return true}
 if(t.dataset.moveEx){const [i,d]=t.dataset.moveEx.split(':').map(Number),j=i+d;if(j>=0&&j<workDraft.length)[workDraft[i],workDraft[j]]=[workDraft[j],workDraft[i]];render();return true}
 if(t.dataset.stepSet){const [ei,si,k,delta]=t.dataset.stepSet.split(':'),set=workDraft[+ei].sets[+si];set[k]=Math.max(0,Math.round(((Number(set[k])||0)+Number(delta))*100)/100);if(k==='weight'){set.originalWeight=set.weight;set.originalUnit=set.unit||'kg'}render();return true}
 if(t.dataset.newMachine!==undefined){persistDraft();machineIndex=Number(t.dataset.newMachine);machineEdit=null;machinePhoto='';profileReturn=modal;modal='machine';render();return true}
 if(t.dataset.newExercise){persistDraft();customEdit=null;profileReturn=modal;modal='custom-exercise';render();return true}
 if(t.dataset.editMachine){machineEdit=db.machines.find(x=>x.id===t.dataset.editMachine);machinePhoto=machineEdit?.photoDataUrl||'';machineIndex=null;profileReturn=null;modal='machine';render();return true}
 if(t.dataset.editCustom){customEdit=db.customExercises.find(x=>x.id===t.dataset.editCustom);profileReturn=null;modal='custom-exercise';render();return true}
 if(t.id==='apply-recommendation'){if(readSession()){resumeSession();return true}const r=recommendationView().raw;const items=r.suggestions||[];workDraft=items.map(x=>({...allExercises().find(e=>e.id===x.exerciseId),...structuredClone(x),id:uid(),sets:x.sets.length?x.sets:[{weight:0,reps:10,unit:'kg',completed:false}]}));workMeta={date:today(),title:'직접 확인하는 운동 초안',...db.checkins?.[today()]};workEditId=null;modal='workout';render();toast('근거와 오늘 상태를 확인하고 종목·중량을 직접 조정하세요.');return true}
 return false;
}
function enhancedChange(t){
 if(t.dataset.ex==='machineId'){const ex=workDraft[Number(t.closest('[data-ei]').dataset.ei)];ex.machineId=t.value||null;const machine=db.machines.find(m=>m.id===ex.machineId);for(const set of ex.sets)if(Number(set.weight)===0)set.unit=machine?.unit||'kg';render();return true}
 if(t.dataset.set==='unit'){const set=workDraft[Number(t.closest('[data-ei]').dataset.ei)].sets[Number(t.closest('[data-si]').dataset.si)];Object.assign(set,convertSetUnit(set,t.value));render();return true}
 if(t.dataset.set==='completed'&&t.checked){startRestTimer(90)}
 if(t.dataset.ex==='name'){const ex=workDraft[Number(t.closest('[data-ei]').dataset.ei)],match=allExercises().find(x=>x.name===t.value);ex.exerciseId=match?.id||null;ex.primaryMuscleIds=match?.primaryMuscleIds||[];ex.secondaryMuscleIds=match?.secondaryMuscleIds||[]}
 return enhancedInput(t);
}
function enhancedInput(t){
 if(t.dataset.set==='unit')return true;
 if(t.dataset.set==='weight'){const set=workDraft[Number(t.closest('[data-ei]').dataset.ei)].sets[Number(t.closest('[data-si]').dataset.si)];set.weight=t.value;set.originalWeight=t.value===''?null:Number(t.value);set.originalUnit=set.unit||'kg';return true}
 if(t.id==='exercise-search'){selection.query=t.value;const start=t.selectionStart;render();const input=document.getElementById('exercise-search');input?.focus();input?.setSelectionRange(start,start);return true}
 if(t.dataset.foodField){const row=batchRows[Number(t.closest('[data-food-row]').dataset.foodRow)];row[t.dataset.foodField]=t.value;const total=document.getElementById('batch-total');if(total)total.textContent=batchSummary(batchRows);return true}
 if(t.closest('#batch-form')&&t.name){if(t.name==='date')batchDate=t.value;if(t.name==='slot'){batchSlot=t.value;batchRows.forEach(x=>x.slot=t.value)};return true}
 return false;
}

let tesseractPromise;async function getTesseract(){if(window.Tesseract)return window.Tesseract;if(!tesseractPromise)tesseractPromise=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='./vendor/tesseract.min.js';s.onload=()=>resolve(window.Tesseract);s.onerror=()=>reject(Error('OCR 도구를 불러오지 못했습니다. 인터넷 연결을 확인하거나 숫자 파일을 사용해 주세요.'));document.head.append(s)});return tesseractPromise}
async function runOCR(){const status=document.getElementById('ocr-status'),file=document.getElementById('inbody-photo').files?.[0];if(!file)throw Error('사진을 선택해 주세요.');status.textContent='인바디 270 결과지의 숫자를 읽고 있습니다…';try{const T=await getTesseract();const result=await recognizeInBody270(file,T);document.getElementById('ocr-text').value=Object.entries(result.raw).map(([k,v])=>`${k}: ${v.trim()}`).join('\n');ocrFields(result.fields);status.textContent='숫자 읽기를 마쳤습니다. 모든 값을 원본과 비교한 뒤 저장해 주세요.'}catch(err){status.textContent=err.message;toast(err.message)}}async function shareWorkout(w){if(!w)return;const t=workoutTotals(w),canvas=document.createElement('canvas');canvas.width=900;canvas.height=920+Math.min(w.exercises.length,8)*54;const c=canvas.getContext('2d');c.fillStyle='#09090e';c.fillRect(0,0,canvas.width,canvas.height);c.fillStyle='#c1a5ff';c.font='bold 26px sans-serif';c.fillText('MYWEIGHTLOG · 마웨로그',48,60);c.fillStyle='#e9e7e1';c.font='bold 43px sans-serif';c.fillText(w.title,48,125);c.fillStyle='#aaa7b4';c.font='25px sans-serif';c.fillText(w.date,48,165);c.fillStyle='#8788ee';c.font='bold 31px sans-serif';c.fillText(`${t.exercises}종목   ${t.sets}세트   ${t.reps}회   ${fmt(t.volume,0)} kg`,48,236);let y=300;for(const e of w.exercises.slice(0,8)){c.fillStyle='#e9e7e1';c.font='24px sans-serif';c.fillText(e.name,48,y);c.fillStyle='#aaa7b4';c.font='20px sans-serif';c.fillText(`${e.kind==='cardio'?`${fmt(e.durationMin)}분`:`완료 ${e.sets.filter(s=>s.completed!==false).length}세트`} · ${e.part}`,650,y);y+=54}const completedExercises=w.exercises.filter(e=>e.kind==='cardio'?(e.durationMin>0||e.distanceKm>0):e.sets.some(s=>s.completed!==false)),primary=[...new Set(completedExercises.flatMap(e=>e.primaryMuscleIds||[]))],secondary=[...new Set(completedExercises.flatMap(e=>e.secondaryMuscleIds||[]))].filter(x=>!primary.includes(x));for(const [i,side] of ['front','back'].entries()){const img=new Image();img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(anatomySvg(primary,secondary,{side,key:'export'}));await img.decode();c.drawImage(img,260+i*200,y+30,180,385)}c.fillStyle='#c1a5ff';c.font='22px sans-serif';c.fillText('테크니컬 아틀라스 · 주 타깃 빨강 / 보조 사선',48,y+455);canvas.toBlob(blob=>{if(!blob){toast('이미지 생성에 실패했습니다.');return}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`myweightlog-${w.date}.png`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('운동 결과 이미지를 저장했습니다.')},'image/png')}
