function profilesHTML(){return `<details class="section card"><summary>내 머신·사용자 종목 관리</summary><h3>머신</h3>${(db.machines||[]).map(x=>`<div class="record"><strong>${esc(x.name)} · ${esc(x.manufacturer)} ${esc(x.model)}</strong><button data-edit-machine="${esc(x.id)}">수정</button></div>`).join('')||'<p class="hint">운동 입력 중 머신을 등록하세요.</p>'}<h3>나만의 종목</h3>${(db.customExercises||[]).map(x=>`<div class="record"><strong>${esc(x.name)}</strong><button data-edit-custom="${esc(x.id)}">수정</button></div>`).join('')||'<p class="hint">운동 도감에서 직접 등록할 수 있습니다.</p>'}</details>`}

function estimateFor(ex){return latestEstimate(db.workouts.map(w=>({...w,exercises:w.exercises.filter(e=>(ex.exerciseId?e.exerciseId===ex.exerciseId:e.name===ex.name)&&(e.machineId||null)===(ex.machineId||null))})),ex.name)}
async function readMachinePhoto(input){const file=input.files?.[0];if(!file)return;if(!/^image\/(jpeg|png|webp)$/.test(file.type)||file.size>10*1024*1024)throw Error('10 MB 이하 JPG·PNG·WebP 사진을 선택하세요.');const bitmap=await createImageBitmap(file);const scale=Math.min(1,800/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();machinePhoto=canvas.toDataURL('image/jpeg',.8);const img=document.getElementById('machine-preview');img.src=machinePhoto;img.hidden=false}

function reviewHTML(){const c=comparePeriods(db,30),w=weeklyReport(db),bodyDays=new Set(db.body.filter(x=>x.date>=w.from&&x.date<=w.to).map(x=>x.date)).size;return `<section class="section card"><h3>이번 주 기록과 이전 기간 비교</h3><p>몸 ${bodyDays}/7일 · 식단 완료/단식 ${w.completeDietDays}/7일 · 운동 ${w.workoutDays}/7일</p><p class="hint">식단 일부 ${w.partialDietDays}일 · 미기록 ${w.missingDietDays}일. 운동 없는 날은 자동으로 휴식으로 판단하지 않습니다.</p><p>직전 30일 대비 운동 ${c.workoutSessionsChange>0?'+':''}${c.workoutSessionsChange}회 · 기록 볼륨 ${fmt(c.volumeChange)} kg</p><p class="hint">식단 평균 차이 ${fmt(c.averageCaloriesChange)} kcal · 두 기간 모두 완료/단식일 기준이며 결측에 따라 비교 의미가 달라집니다. ${esc(c.note)}</p></section>`}

function loadAtlasHTML(key){const r=recommendWorkout(db,today());return `${muscleMapHTML([],[],{key,mode:'load',loads:r.loads})}<div class="atlas-load-list">${r.loads.map(x=>`<div class="record"><strong>${esc(MUSCLE_LABELS[x.muscleId]||x.muscleId)} · ${esc(x.level)}</strong><small>지표 ${fmt(x.score)} · 가중 세트 ${fmt(x.sets)}<br>마지막 기록 ${esc(x.lastDate)}</small></div>`).join('')||'<p class="hint">최근 완료 세트가 없어 부위별 부하를 판단하지 않습니다.</p>'}</div><details><summary>계산 근거와 미확인 정보</summary><p class="hint">${esc(r.note)}</p><p class="hint">미확인: ${esc(r.missing.join(', ')||'없음')}</p></details>`}
